import express from 'express';

const TOKEN = { 'token-rina': { id: 1, peran: 'pelanggan' }, 'token-budi': { id: 2, peran: 'pelanggan' }, 'token-sari': { id: 3, peran: 'admin' } };
const pesanan = [{ id: 15, penggunaId: 1, menu: 'Kopi' }, { id: 16, penggunaId: 2, menu: 'Teh' }];
const butuhLogin = (req, res, next) => {
  req.pengguna = TOKEN[(req.get('authorization') ?? '').replace('Bearer ', '')];
  if (!req.pengguna) return res.sendStatus(401);
  next();
};
const butuhPeran = (peran) => (req, res, next) => (req.pengguna.peran === peran ? next() : res.sendStatus(403));

const app = express();
app.get('/pesanan/:id', butuhLogin, (req, res) => {
  const p = pesanan.find((x) => x.id === Number(req.params.id));
  const boleh = p && (p.penggunaId === req.pengguna.id || req.pengguna.peran === 'admin');
  if (!boleh) return res.status(404).json({ error: 'Pesanan tidak ada' });
  res.json(p);
});
app.delete('/pesanan/:id', butuhLogin, butuhPeran('admin'), (req, res) => res.sendStatus(204));
const server = app.listen(3000);

const coba = async (method, jalur, token) => {
  const r = await fetch('http://localhost:3000' + jalur, { method, headers: { Authorization: `Bearer ${token}` } });
  console.log(token, method, jalur, r.status);
};
await coba('GET', '/pesanan/15', 'token-rina');
await coba('GET', '/pesanan/16', 'token-rina');
await coba('GET', '/pesanan/16', 'token-sari');
await coba('DELETE', '/pesanan/15', 'token-rina');
await coba('DELETE', '/pesanan/15', 'token-sari');
server.close();

